window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["intercom"]={html:"<div class=\"own-intercom\">\n  <!-- ── NAV ─────────────────────────────────────────────────────────── -->\n  <header class=\"nav\" id=\"intercomNav\">\n    <div class=\"wrap nav-in\">\n      <a class=\"brand\" href=\"#intercomTop\" aria-label=\"Northwind home\">\n        <span class=\"brand-mark\" aria-hidden=\"true\">\n          <svg viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"4\" width=\"3.2\" height=\"12\" rx=\"1.6\"/><rect x=\"8.4\" y=\"2.5\" width=\"3.2\" height=\"15\" rx=\"1.6\"/><rect x=\"13.8\" y=\"4\" width=\"3.2\" height=\"12\" rx=\"1.6\"/><rect x=\"19.2\" y=\"6.5\" width=\"2.6\" height=\"7\" rx=\"1.3\"/><circle cx=\"4.6\" cy=\"19.5\" r=\"1.7\"/><circle cx=\"19.4\" cy=\"19.5\" r=\"1.7\"/></svg>\n        </span>\n        <span class=\"brand-name\">Northwind</span>\n      </a>\n      <nav class=\"nav-links\" aria-label=\"Primary\">\n        <a href=\"#intercomProduct\">Product</a>\n        <a href=\"#intercomPlatform\">Platform</a>\n        <a href=\"#intercomCustomers\">Customers</a>\n        <a href=\"#intercomPricing\">Pricing</a>\n        <a href=\"#intercomFaq\">FAQ</a>\n      </nav>\n      <div class=\"nav-actions\">\n        <a class=\"btn btn-tertiary\" href=\"#\">Log in</a>\n        <a class=\"btn btn-primary\" href=\"#intercomPricing\">Sign up</a>\n        <button class=\"nav-toggle\" type=\"button\" aria-label=\"Open menu\" aria-expanded=\"false\" data-nav-toggle>\n          <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 7h16M4 12h16M4 17h16\"/></svg>\n        </button>\n      </div>\n    </div>\n    <div class=\"nav-drawer\" hidden data-nav-drawer>\n      <a href=\"#intercomProduct\">Product</a>\n      <a href=\"#intercomPlatform\">Platform</a>\n      <a href=\"#intercomCustomers\">Customers</a>\n      <a href=\"#intercomPricing\">Pricing</a>\n      <a href=\"#intercomFaq\">FAQ</a>\n      <a class=\"drawer-cta\" href=\"#intercomPricing\">Sign up free</a>\n    </div>\n  </header>\n\n  <main id=\"intercomTop\">\n    <!-- ── HERO ──────────────────────────────────────────────────────── -->\n    <section class=\"hero\">\n      <div class=\"wrap hero-in\">\n        <div class=\"hero-copy reveal\" data-reveal>\n          <p class=\"eyebrow\">Operations support, answered</p>\n          <h1 class=\"display-xl\">The inbox that runs your operation.</h1>\n        <p class=\"hero-lead\">Northwind brings every ticket, shipment, and revenue signal into one calm workspace — so your team resolves the day instead of chasing it.</p>\n          <div class=\"hero-cta\">\n            <a class=\"btn btn-primary btn-lg\" href=\"#intercomPricing\">Start free</a>\n            <a class=\"btn btn-secondary btn-lg\" href=\"#intercomProduct\">Book a demo</a>\n          </div>\n          <p class=\"hero-note\">Free for 14 days · No card required</p>\n        </div>\n        <div class=\"hero-mock reveal\" data-reveal aria-label=\"Northwind inbox preview\">\n          <div class=\"mock\">\n            <div class=\"mock-side\" aria-hidden=\"true\">\n              <span class=\"ms on\">Inbox</span><span class=\"ms\">Assigned</span><span class=\"ms\">Reports</span><span class=\"ms\">Settings</span>\n            </div>\n            <div class=\"mock-main\">\n              <div class=\"mock-top\">\n                <span class=\"mock-title\">My inbox</span>\n                <span class=\"mock-badge\">6 open</span>\n              </div>\n              <ul class=\"mock-list\" id=\"intercomList\"></ul>\n            </div>\n          </div>\n          <div class=\"mock-float\" aria-hidden=\"true\">\n            <span class=\"mf-dot\"></span>Fin resolved 62% without a human\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <!-- ── LOGO STRIP ────────────────────────────────────────────────── -->\n    <section class=\"logos\" aria-label=\"Customers\">\n      <div class=\"wrap logos-in\" id=\"intercomLogos\"></div>\n    </section>\n\n    <!-- ── PRODUCT: SIGNATURE MOCKUP ─────────────────────────────────── -->\n    <section class=\"section\" id=\"intercomProduct\">\n      <div class=\"wrap\">\n        <div class=\"sec-head center reveal\" data-reveal>\n          <p class=\"eyebrow\">The workspace</p>\n          <h2 class=\"display-lg\">Everything your team needs, in the order it happens.</h2>\n          <p class=\"lead\">Ticket queues, customer context, and the metrics behind them — one surface, no tab-switching.</p>\n        </div>\n        <div class=\"mock-wide reveal\" data-reveal>\n          <div class=\"mw-bar\">\n            <span class=\"mw-crumb\">Support &nbsp;/&nbsp; <b>Today</b></span>\n            <span class=\"mw-seg\"><span class=\"on\">Queue</span><span>Analytics</span><span>Routing</span></span>\n          </div>\n          <div class=\"mw-grid\">\n            <div class=\"mw-panel\">\n              <div class=\"mw-panel-head\"><span>Volume this week</span><span class=\"ok\">+8.4%</span></div>\n              <div class=\"mw-chart\">\n                <svg viewBox=\"0 0 320 120\" preserveAspectRatio=\"none\" aria-hidden=\"true\">\n                  <g fill=\"#ff5600\" opacity=\".16\">\n                    <rect x=\"8\" y=\"66\" width=\"28\" height=\"54\"/><rect x=\"46\" y=\"50\" width=\"28\" height=\"70\"/><rect x=\"84\" y=\"72\" width=\"28\" height=\"48\"/><rect x=\"122\" y=\"38\" width=\"28\" height=\"82\"/><rect x=\"160\" y=\"58\" width=\"28\" height=\"62\"/><rect x=\"198\" y=\"28\" width=\"28\" height=\"92\"/><rect x=\"236\" y=\"46\" width=\"28\" height=\"74\"/><rect x=\"274\" y=\"20\" width=\"28\" height=\"100\"/>\n                  </g>\n                  <polyline points=\"22,58 60,42 98,64 136,30 174,50 212,20 250,38 288,12\" fill=\"none\" stroke=\"#ff5600\" stroke-width=\"2.5\"/>\n                </svg>\n              </div>\n            </div>\n            <div class=\"mw-panel\">\n              <div class=\"mw-panel-head\"><span>Resolution by channel</span></div>\n              <ul class=\"mw-rows\" id=\"intercomChannels\"></ul>\n            </div>\n            <div class=\"mw-panel\">\n              <div class=\"mw-panel-head\"><span>CSAT</span><span class=\"ok\">4.8 / 5</span></div>\n              <div class=\"mw-big\" data-count=\"4820\" data-suffix=\"\">0</div>\n              <p class=\"mw-sub\">responses this month</p>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <!-- ── FEATURE CARDS ─────────────────────────────────────────────── -->\n    <section class=\"section tight\" id=\"intercomPlatform\">\n      <div class=\"wrap\">\n        <div class=\"grid3\">\n          <article class=\"fcard reveal\" data-reveal>\n            <span class=\"fcard-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 6h16v12H4z\"/><path d=\"m4 7 8 6 8-6\"/></svg></span>\n            <h3>A shared inbox</h3>\n            <p>Route every conversation to the right owner with rules your team can read and change.</p>\n          </article>\n          <article class=\"fcard reveal\" data-reveal>\n            <span class=\"fcard-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M3 20V8M9 20V4M15 20v-9M21 20v-13\"/></svg></span>\n            <h3>Operational analytics</h3>\n            <p>Throughput, backlog, and SLA in one board — trace any spike to the tickets behind it.</p>\n          </article>\n          <article class=\"fcard reveal\" data-reveal>\n            <span class=\"fcard-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M8 12h8M12 8v8\"/></svg></span>\n            <h3>Fin, your AI agent</h3>\n            <p>Deflect the repeat questions, escalate the hard ones, and hand off with full context.</p>\n            <span class=\"fin-badge\">Fin</span>\n          </article>\n        </div>\n      </div>\n    </section>\n\n    <!-- ── TESTIMONIALS ──────────────────────────────────────────────── -->\n    <section class=\"section\" id=\"intercomCustomers\">\n      <div class=\"wrap\">\n        <div class=\"sec-head reveal\" data-reveal>\n          <p class=\"eyebrow\">Customers</p>\n          <h2 class=\"display-lg\">Teams that stopped dreading Monday.</h2>\n        </div>\n        <div class=\"quotes\">\n          <figure class=\"quote reveal\" data-reveal>\n            <blockquote>“Our first-response time halved in three weeks. Fin takes the repetitive 60% and the team handles what matters.”</blockquote>\n            <figcaption><span class=\"av\">MK</span><span><b>Mira Kessler</b>Head of Support, Vector Freight</span></figcaption>\n          </figure>\n          <figure class=\"quote reveal\" data-reveal>\n            <blockquote>“The reporting finally matches reality. Finance and support look at the same number now.”</blockquote>\n            <figcaption><span class=\"av\">DO</span><span><b>Daniel Okafor</b>Ops Director, Kestrel Bank</span></figcaption>\n          </figure>\n        </div>\n      </div>\n    </section>\n\n    <!-- ── BLACK QUOTE STRIP ─────────────────────────────────────────── -->\n    <section class=\"blackstrip\">\n      <div class=\"wrap\">\n        <blockquote>“Northwind is the first tool our floor actually likes using.”</blockquote>\n        <p>Lena Sørensen — Director of Operations, Aperture Foods</p>\n      </div>\n    </section>\n\n    <!-- ── PRICING ───────────────────────────────────────────────────── -->\n    <section class=\"section\" id=\"intercomPricing\">\n      <div class=\"wrap\">\n        <div class=\"sec-head center reveal\" data-reveal>\n          <p class=\"eyebrow\">Pricing</p>\n          <h2 class=\"display-lg\">Simple plans, no surprises.</h2>\n          <div class=\"tabs\" role=\"tablist\" aria-label=\"Billing cadence\">\n            <button class=\"tab on\" type=\"button\" role=\"tab\" aria-selected=\"true\" data-cycle=\"monthly\">Monthly</button>\n            <button class=\"tab\" type=\"button\" role=\"tab\" aria-selected=\"false\" data-cycle=\"annual\">Annual <em>save 17%</em></button>\n          </div>\n        </div>\n        <div class=\"grid3 tiers\">\n          <article class=\"tier reveal\" data-reveal>\n            <h3>Essential</h3>\n            <p class=\"tier-note\">For a small team getting organised.</p>\n            <p class=\"price\"><span data-price=\"29\">$29</span><small>/seat/mo</small></p>\n            <ul><li>Shared inbox</li><li>Basic reporting</li><li>Email support</li></ul>\n            <a class=\"btn btn-secondary btn-block\" href=\"#\">Start free</a>\n          </article>\n          <article class=\"tier tier-feat reveal\" data-reveal>\n            <span class=\"tier-badge\">Most popular</span>\n            <h3>Advanced</h3>\n            <p class=\"tier-note\">For operations running every day.</p>\n            <p class=\"price\"><span data-price=\"85\">$85</span><small>/seat/mo</small></p>\n            <ul><li>Everything in Essential</li><li>Automation rules</li><li>Fin AI agent</li><li>SSO</li></ul>\n            <a class=\"btn btn-fin btn-block\" href=\"#\">Get Advanced</a>\n          </article>\n          <article class=\"tier reveal\" data-reveal>\n            <h3>Expert</h3>\n            <p class=\"tier-note\">For enterprise operations at scale.</p>\n            <p class=\"price\"><span data-price=\"132\">$132</span><small>/seat/mo</small></p>\n            <ul><li>Everything in Advanced</li><li>Audit log &amp; retention</li><li>Data residency</li><li>Dedicated CSM</li></ul>\n            <a class=\"btn btn-secondary btn-block\" href=\"#\">Contact sales</a>\n          </article>\n        </div>\n      </div>\n    </section>\n\n    <!-- ── FAQ ───────────────────────────────────────────────────────── -->\n    <section class=\"section tight\" id=\"intercomFaq\">\n      <div class=\"wrap wrap-narrow\">\n        <div class=\"sec-head reveal\" data-reveal>\n          <p class=\"eyebrow\">FAQ</p>\n          <h2 class=\"display-lg\">Questions, answered.</h2>\n        </div>\n        <div class=\"faq\" id=\"intercomFaqList\"></div>\n      </div>\n    </section>\n\n    <!-- ── CTA BANNER ────────────────────────────────────────────────── -->\n    <section class=\"section\">\n      <div class=\"wrap\">\n        <div class=\"cta reveal\" data-reveal>\n          <div>\n            <h2>Bring the whole operation into one inbox.</h2>\n            <p>Set up Northwind for your team in an afternoon. Import your queues and keep working.</p>\n          </div>\n          <div class=\"cta-actions\">\n            <a class=\"btn btn-primary btn-lg\" href=\"#\">Sign up free</a>\n            <a class=\"btn btn-secondary btn-lg\" href=\"#intercomProduct\">Book a demo</a>\n          </div>\n        </div>\n      </div>\n    </section>\n  </main>\n\n  <!-- ── FOOTER ──────────────────────────────────────────────────────── -->\n  <footer class=\"foot\">\n    <div class=\"wrap foot-in\">\n      <div class=\"foot-brand\">\n        <span class=\"brand-name\">Northwind</span>\n        <p>Operations support and analytics, in one calm workspace.</p>\n      </div>\n      <nav class=\"foot-cols\" aria-label=\"Footer\">\n        <div><h4>Product</h4><a href=\"#intercomProduct\">Overview</a><a href=\"#intercomPlatform\">Platform</a><a href=\"#intercomPricing\">Pricing</a></div>\n        <div><h4>Company</h4><a href=\"#\">About</a><a href=\"#\">Careers</a><a href=\"#intercomCustomers\">Customers</a></div>\n        <div><h4>Resources</h4><a href=\"#\">Docs</a><a href=\"#\">API</a><a href=\"#\">Status</a></div>\n        <div><h4>Legal</h4><a href=\"#\">Privacy</a><a href=\"#\">Terms</a><a href=\"#\">Security</a></div>\n      </nav>\n    </div>\n    <div class=\"wrap foot-base\">\n      <span>© 2026 Northwind Analytics, Inc.</span>\n      <span>Sample content — showcase only</span>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ INTERCOM — Northwind operations support in Intercom's editorial language ═\n   Warm cream canvas (#f5f1ec), charcoal type, floating white cards with thin\n   hairlines, product mockups as the protagonist, Fin Orange (#ff5600) reserved\n   for the Fin agent. Scoped under `.own-intercom`. */\n\n.own-intercom {\n  --canvas: #f5f1ec;\n  --surface-1: #ffffff;\n  --surface-2: #ebe7e1;\n  --ink: #111111;\n  --ink-muted: #626260;\n  --ink-subtle: #6a6a67;\n  --ink-tertiary: #6c6c69;\n  --inverse-canvas: #000000;\n  --hairline: #d3cec6;\n  --hairline-soft: #ebe7e1;\n  --fin-orange: #ff5600;\n  --report-blue: #65b5ff;\n  --report-green: #0bdf50;\n  --report-pink: #ff2067;\n  --report-lime: #b3e01c;\n  --report-cyan: #03b2cb;\n\n  --f-sans: 'Saans', 'Inter', ui-sans-serif, system-ui, sans-serif;\n  --f-mono: 'SaansMono', 'JetBrains Mono', ui-monospace, monospace;\n\n  --gut: clamp(18px, 4.5cqi, 32px);\n  --sec: clamp(56px, 8cqi, 96px);\n\n  position: relative;\n  background: var(--canvas);\n  color: var(--ink);\n  font-family: var(--f-sans);\n  font-size: 16px;\n  line-height: 1.5;\n  text-align: left;\n  overflow-x: clip;\n  -webkit-font-smoothing: antialiased;\n}\n.own-intercom *, .own-intercom *::before, .own-intercom *::after { box-sizing: border-box; }\n.own-intercom p { margin: 0; }\n.own-intercom a { color: inherit; text-decoration: none; }\n.own-intercom img, .own-intercom svg { display: block; }\n.own-intercom button, .own-intercom input { font: inherit; }\n.own-intercom :focus-visible { outline: 2px solid var(--ink); outline-offset: 2px; border-radius: 4px; }\n\n.own-intercom .wrap { width: 100%; max-width: 1280px; margin: 0 auto; padding: 0 var(--gut); }\n.own-intercom .wrap-narrow { max-width: 820px; }\n\n/* ── type ────────────────────────────────────────────────────────────── */\n.own-intercom .eyebrow { font-size: 14px; font-weight: 500; letter-spacing: 0.2px; color: var(--fin-orange); margin-bottom: 16px; }\n.own-intercom .display-xl { font-family: var(--f-sans); font-weight: 500; font-size: clamp(40px, 6.2cqi, 72px); line-height: 1.05; letter-spacing: -2px; max-width: 15ch; text-wrap: balance; }\n.own-intercom .display-lg { font-family: var(--f-sans); font-weight: 500; font-size: clamp(30px, 4.4cqi, 56px); line-height: 1.1; letter-spacing: -1.4px; max-width: 20ch; }\n.own-intercom .lead { color: var(--ink-muted); margin-top: 16px; max-width: 60ch; font-size: 18px; line-height: 1.5; }\n\n/* ── buttons ─────────────────────────────────────────────────────────── */\n.own-intercom .btn {\n  display: inline-flex; align-items: center; justify-content: center; gap: 8px;\n  padding: 10px 18px; border: 1px solid transparent; border-radius: 8px;\n  font-family: var(--f-sans); font-size: 15px; font-weight: 500;\n  cursor: pointer; white-space: nowrap;\n  transition: background-color .15s, border-color .15s, color .15s, transform .15s;\n}\n.own-intercom .btn-primary { background: var(--ink); color: #fff; }\n.own-intercom .btn-primary:hover { background: #000; }\n.own-intercom .btn-secondary { background: var(--surface-1); color: var(--ink); border-color: var(--hairline); }\n.own-intercom .btn-secondary:hover { border-color: var(--ink); }\n.own-intercom .btn-tertiary { background: transparent; color: var(--ink); }\n.own-intercom .btn-tertiary:hover { background: var(--surface-1); }\n.own-intercom .btn-fin { background: var(--fin-orange); color: #fff; }\n.own-intercom .btn-fin:hover { background: #e64d00; }\n.own-intercom .btn-lg { padding: 13px 22px; font-size: 16px; }\n.own-intercom .btn-block { display: flex; width: 100%; }\n\n/* ── nav ─────────────────────────────────────────────────────────────── */\n.own-intercom .nav { position: sticky; top: 68px; z-index: 40; background: var(--canvas); border-bottom: 1px solid transparent; transition: border-color .2s, background-color .2s; }\n.own-intercom .nav.is-stuck { border-bottom-color: var(--hairline); background: color-mix(in srgb, var(--canvas) 94%, transparent); -webkit-backdrop-filter: blur(10px); backdrop-filter: blur(10px); }\n.own-intercom .nav-in { display: flex; align-items: center; gap: 28px; height: 56px; }\n.own-intercom .brand { display: flex; align-items: center; gap: 9px; font-weight: 600; font-size: 18px; letter-spacing: -0.3px; }\n.own-intercom .brand-mark { display: grid; place-items: center; width: 26px; height: 26px; border-radius: 7px; color: #fff; background: var(--ink); }\n.own-intercom .brand-mark svg { width: 17px; height: 17px; fill: currentColor; }\n.own-intercom .nav-links { display: flex; align-items: center; gap: 4px; margin: 0 auto; }\n.own-intercom .nav-links a { padding: 7px 12px; border-radius: 8px; font-size: 15px; color: var(--ink-muted); transition: color .15s, background-color .15s; }\n.own-intercom .nav-links a:hover { color: var(--ink); background: var(--surface-1); }\n.own-intercom .nav-actions { display: flex; align-items: center; gap: 8px; }\n.own-intercom .nav-toggle { display: none; place-items: center; width: 38px; height: 38px; border-radius: 8px; border: 1px solid var(--hairline); background: var(--surface-1); color: var(--ink); cursor: pointer; }\n.own-intercom .nav-toggle svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }\n.own-intercom .nav-drawer { display: none; }\n.own-intercom .nav-drawer[hidden] { display: none; }\n\n/* ── hero ────────────────────────────────────────────────────────────── */\n.own-intercom .hero { padding: clamp(48px, 7cqi, 96px) 0 clamp(32px, 5cqi, 56px); }\n.own-intercom .hero-in { display: grid; grid-template-columns: 0.95fr 1.05fr; gap: clamp(32px, 5cqi, 64px); align-items: center; }\n.own-intercom .hero-lead { color: var(--ink-muted); margin: 22px 0 28px; max-width: 48ch; font-size: 18px; line-height: 1.5; }\n.own-intercom .hero-cta { display: flex; flex-wrap: wrap; gap: 12px; }\n.own-intercom .hero-note { margin-top: 18px; font-size: 13px; color: var(--ink-subtle); }\n\n/* ── product mockups ─────────────────────────────────────────────────── */\n.own-intercom .hero-mock { position: relative; }\n.own-intercom .mock { display: grid; grid-template-columns: 150px 1fr; border-radius: 16px; background: var(--surface-1); border: 1px solid var(--hairline); overflow: hidden; box-shadow: 0 24px 60px -34px rgba(17, 17, 17, .35); }\n.own-intercom .mock-side { display: flex; flex-direction: column; gap: 2px; padding: 18px 14px; border-right: 1px solid var(--hairline-soft); background: var(--surface-2); }\n.own-intercom .ms { padding: 8px 10px; border-radius: 8px; font-size: 13px; color: var(--ink-muted); }\n.own-intercom .ms.on { background: var(--surface-1); color: var(--ink); font-weight: 500; }\n.own-intercom .mock-main { padding: 18px; }\n.own-intercom .mock-top { display: flex; align-items: center; justify-content: space-between; padding-bottom: 14px; border-bottom: 1px solid var(--hairline-soft); }\n.own-intercom .mock-title { font-size: 15px; font-weight: 500; }\n.own-intercom .mock-badge { font-size: 12px; color: var(--fin-orange); background: color-mix(in srgb, var(--fin-orange) 12%, transparent); padding: 3px 9px; border-radius: 999px; }\n.own-intercom .mock-list { list-style: none; margin: 0; padding: 0; }\n.own-intercom .mi { display: grid; grid-template-columns: 26px 1fr auto; gap: 12px; align-items: center; padding: 12px 2px; border-bottom: 1px solid var(--hairline-soft); }\n.own-intercom .mi:last-child { border-bottom: 0; }\n.own-intercom .mi-av { width: 26px; height: 26px; border-radius: 50%; display: grid; place-items: center; font-size: 10px; font-weight: 600; color: #fff; }\n.own-intercom .mi-body { min-width: 0; }\n.own-intercom .mi-body b { display: block; font-size: 13.5px; font-weight: 500; }\n.own-intercom .mi-body span { display: block; font-size: 12.5px; color: var(--ink-subtle); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.own-intercom .mi-time { font-size: 12px; color: var(--ink-tertiary); }\n.own-intercom .mock-float { position: absolute; left: -16px; bottom: -18px; display: flex; align-items: center; gap: 8px; padding: 10px 14px; border-radius: 12px; background: var(--inverse-canvas); color: #fff; font-size: 13px; box-shadow: 0 16px 40px -20px rgba(0,0,0,.6); }\n.own-intercom .mf-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--fin-orange); }\n\n/* ── logos ───────────────────────────────────────────────────────────── */\n.own-intercom .logos { padding: clamp(28px, 4cqi, 44px) 0; }\n.own-intercom .logos-in { display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: 20px 44px; }\n.own-intercom .logos-cap { width: 100%; text-align: center; font-size: 13px; color: var(--ink-subtle); }\n.own-intercom .lg { font-weight: 600; font-size: 17px; letter-spacing: -0.2px; color: var(--ink-muted); opacity: .8; }\n\n/* ── sections ────────────────────────────────────────────────────────── */\n.own-intercom .section { padding: var(--sec) 0; }\n.own-intercom .section.tight { padding-top: clamp(32px, 5cqi, 56px); }\n.own-intercom .sec-head { margin-bottom: clamp(32px, 5cqi, 52px); }\n.own-intercom .sec-head.center { text-align: center; }\n.own-intercom .sec-head.center .display-lg,\n.own-intercom .sec-head.center .lead { margin-left: auto; margin-right: auto; }\n\n/* ── wide product mockup ─────────────────────────────────────────────── */\n.own-intercom .mock-wide { border-radius: 16px; background: var(--surface-1); border: 1px solid var(--hairline); overflow: hidden; box-shadow: 0 30px 70px -40px rgba(17, 17, 17, .35); }\n.own-intercom .mw-bar { display: flex; align-items: center; justify-content: space-between; padding: 14px 20px; border-bottom: 1px solid var(--hairline-soft); background: var(--surface-2); }\n.own-intercom .mw-crumb { font-size: 13px; color: var(--ink-muted); }\n.own-intercom .mw-crumb b { color: var(--ink); font-weight: 500; }\n.own-intercom .mw-seg { display: flex; gap: 2px; padding: 3px; border-radius: 8px; background: var(--canvas); }\n.own-intercom .mw-seg span { padding: 5px 12px; border-radius: 6px; font-size: 12.5px; color: var(--ink-subtle); }\n.own-intercom .mw-seg span.on { background: var(--surface-1); color: var(--ink); box-shadow: 0 1px 2px rgba(0,0,0,.06); }\n.own-intercom .mw-grid { display: grid; grid-template-columns: 1.4fr 1fr 1fr; gap: 1px; background: var(--hairline-soft); }\n.own-intercom .mw-panel { background: var(--surface-1); padding: 22px; }\n.own-intercom .mw-panel-head { display: flex; align-items: center; justify-content: space-between; font-size: 13px; color: var(--ink-muted); margin-bottom: 16px; }\n.own-intercom .mw-panel-head .ok { color: var(--report-green); font-weight: 500; }\n.own-intercom .mw-chart { height: 130px; }\n.own-intercom .mw-chart svg { width: 100%; height: 100%; }\n.own-intercom .mw-rows { list-style: none; margin: 0; padding: 0; display: grid; gap: 14px; }\n.own-intercom .mw-rows li { display: grid; gap: 7px; }\n.own-intercom .mw-rows .mr-top { display: flex; justify-content: space-between; font-size: 13px; color: var(--ink-muted); }\n.own-intercom .mw-rows .mr-top b { color: var(--ink); font-weight: 500; }\n.own-intercom .mw-rows .mr-bar { height: 6px; border-radius: 3px; background: var(--surface-2); overflow: hidden; }\n.own-intercom .mw-rows .mr-bar i { display: block; height: 100%; width: var(--w); border-radius: 3px; background: var(--c, var(--report-blue)); }\n.own-intercom .mw-big { font-family: var(--f-sans); font-size: 40px; font-weight: 500; letter-spacing: -1.5px; }\n.own-intercom .mw-sub { font-size: 13px; color: var(--ink-subtle); margin-top: 6px; }\n\n/* ── feature cards ───────────────────────────────────────────────────── */\n.own-intercom .grid3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }\n.own-intercom .fcard { position: relative; background: var(--surface-1); border: 1px solid var(--hairline); border-radius: 12px; padding: 24px; display: flex; flex-direction: column; gap: 12px; }\n.own-intercom .fcard-icon { width: 40px; height: 40px; border-radius: 10px; display: grid; place-items: center; background: var(--surface-2); color: var(--ink); }\n.own-intercom .fcard-icon svg { width: 22px; height: 22px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }\n.own-intercom .fcard h3 { font-size: 22px; font-weight: 500; letter-spacing: -0.3px; margin: 8px 0 0; }\n.own-intercom .fcard p { color: var(--ink-muted); font-size: 15px; line-height: 1.5; }\n.own-intercom .fin-badge { position: absolute; top: 22px; right: 22px; font-size: 12px; font-weight: 500; color: #fff; background: var(--fin-orange); padding: 3px 10px; border-radius: 999px; }\n\n/* ── quotes ──────────────────────────────────────────────────────────── */\n.own-intercom .quotes { display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; }\n.own-intercom .quote { margin: 0; background: var(--surface-1); border: 1px solid var(--hairline); border-radius: 12px; padding: 32px; display: flex; flex-direction: column; gap: 22px; }\n.own-intercom .quote blockquote { margin: 0; font-size: 18px; line-height: 1.5; letter-spacing: -0.1px; }\n.own-intercom .quote figcaption { display: flex; align-items: center; gap: 12px; margin-top: auto; }\n.own-intercom .av { width: 42px; height: 42px; border-radius: 50%; display: grid; place-items: center; background: var(--ink); color: #fff; font-size: 13px; font-weight: 500; flex: none; }\n.own-intercom .quote figcaption span:last-child { display: grid; font-size: 12.5px; color: var(--ink-subtle); }\n.own-intercom .quote figcaption b { color: var(--ink); font-weight: 500; font-size: 14px; }\n\n/* ── black strip ─────────────────────────────────────────────────────── */\n.own-intercom .blackstrip { background: var(--inverse-canvas); color: #fff; padding: clamp(56px, 8cqi, 96px) 0; }\n.own-intercom .blackstrip blockquote { margin: 0; font-size: clamp(26px, 3.8cqi, 44px); font-weight: 500; line-height: 1.15; letter-spacing: -1px; max-width: 22ch; }\n.own-intercom .blackstrip p { margin-top: 22px; color: #9c9fa5; font-size: 14px; }\n\n/* ── pricing ─────────────────────────────────────────────────────────── */\n.own-intercom .tabs { display: inline-flex; gap: 4px; margin-top: 24px; padding: 4px; border-radius: 999px; background: var(--surface-1); border: 1px solid var(--hairline); }\n.own-intercom .tab { padding: 8px 16px; border: 0; border-radius: 999px; background: transparent; color: var(--ink-muted); font-size: 14px; font-weight: 500; cursor: pointer; transition: background-color .18s, color .18s; }\n.own-intercom .tab em { font-style: normal; font-size: 12px; color: var(--fin-orange); }\n.own-intercom .tab.on { background: var(--canvas); color: var(--ink); }\n.own-intercom .tiers { align-items: stretch; }\n.own-intercom .tier { position: relative; background: var(--surface-1); border: 1px solid var(--hairline); border-radius: 12px; padding: 24px; display: flex; flex-direction: column; }\n.own-intercom .tier-feat { background: var(--canvas); border-color: var(--ink); }\n.own-intercom .tier-badge { position: absolute; top: -12px; left: 24px; font-size: 12px; font-weight: 500; padding: 3px 10px; border-radius: 999px; background: var(--ink); color: #fff; }\n.own-intercom .tier h3 { font-size: 20px; font-weight: 500; margin: 6px 0 4px; }\n.own-intercom .tier-note { color: var(--ink-muted); font-size: 14px; min-height: 42px; }\n.own-intercom .price { display: flex; align-items: baseline; gap: 4px; margin: 18px 0; }\n.own-intercom .price span { font-size: 40px; font-weight: 500; letter-spacing: -1.5px; }\n.own-intercom .price small { color: var(--ink-subtle); font-size: 13px; }\n.own-intercom .tier ul { list-style: none; margin: 0 0 24px; padding: 0; display: grid; gap: 11px; flex: 1; }\n.own-intercom .tier li { position: relative; padding-left: 24px; font-size: 14.5px; color: var(--ink-muted); }\n.own-intercom .tier li::before { content: ''; position: absolute; left: 2px; top: 7px; width: 11px; height: 6px; border-left: 2px solid var(--ink); border-bottom: 2px solid var(--ink); transform: rotate(-45deg); }\n\n/* ── faq ─────────────────────────────────────────────────────────────── */\n.own-intercom .faq { border-top: 1px solid var(--hairline-soft); }\n.own-intercom .faq-item { border-bottom: 1px solid var(--hairline-soft); }\n.own-intercom .faq-q { width: 100%; display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 24px 4px; background: none; border: 0; text-align: left; font-size: 17px; font-weight: 500; color: var(--ink); cursor: pointer; }\n.own-intercom .faq-q svg { width: 20px; height: 20px; flex: none; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; transition: transform .25s; }\n.own-intercom .faq-item.open .faq-q svg { transform: rotate(180deg); }\n.own-intercom .faq-a { display: grid; grid-template-rows: 0fr; transition: grid-template-rows .3s ease; }\n.own-intercom .faq-item.open .faq-a { grid-template-rows: 1fr; }\n.own-intercom .faq-a > div { overflow: hidden; }\n.own-intercom .faq-a p { padding: 0 4px 24px; color: var(--ink-muted); font-size: 15px; line-height: 1.6; max-width: 68ch; }\n\n/* ── cta ─────────────────────────────────────────────────────────────── */\n.own-intercom .cta { display: flex; align-items: center; justify-content: space-between; gap: 32px; flex-wrap: wrap; padding: clamp(32px, 5cqi, 48px); border-radius: 12px; background: var(--surface-1); border: 1px solid var(--hairline); }\n.own-intercom .cta h2 { font-size: clamp(24px, 3cqi, 40px); font-weight: 500; letter-spacing: -0.8px; margin: 0 0 10px; max-width: 20ch; }\n.own-intercom .cta p { color: var(--ink-muted); max-width: 48ch; }\n.own-intercom .cta-actions { display: flex; gap: 12px; flex-wrap: wrap; }\n\n/* ── footer ──────────────────────────────────────────────────────────── */\n.own-intercom .foot { padding: clamp(48px, 6cqi, 64px) 0 32px; border-top: 1px solid var(--hairline); }\n.own-intercom .foot-in { display: grid; grid-template-columns: 1.2fr 2.6fr; gap: 40px; }\n.own-intercom .foot-brand .brand-name { font-weight: 600; font-size: 18px; }\n.own-intercom .foot-brand p { color: var(--ink-subtle); font-size: 14px; margin-top: 10px; max-width: 30ch; }\n.own-intercom .foot-cols { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }\n.own-intercom .foot-cols h4 { font-size: 13px; font-weight: 500; color: var(--ink); margin: 0 0 14px; }\n.own-intercom .foot-cols a { display: block; font-size: 14px; color: var(--ink-subtle); padding: 5px 0; transition: color .15s; }\n.own-intercom .foot-cols a:hover { color: var(--ink); }\n.own-intercom .foot-base { display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap; margin-top: 44px; padding-top: 22px; border-top: 1px solid var(--hairline-soft); font-size: 12.5px; color: var(--ink-subtle); }\n\n/* ── reveal ──────────────────────────────────────────────────────────── */\n.own-intercom .reveal { opacity: 0; transform: translateY(20px); transition: opacity .65s ease, transform .65s ease; }\n.own-intercom .reveal.in { opacity: 1; transform: none; }\n\n/* ── responsive ──────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-intercom .nav-links { display: none; }\n  .own-intercom .nav-toggle { display: grid; }\n  .own-intercom .nav-drawer:not([hidden]) { display: grid; gap: 2px; padding: 8px var(--gut) 16px; border-top: 1px solid var(--hairline); background: var(--canvas); }\n  .own-intercom .nav-drawer a { padding: 12px 8px; border-radius: 8px; font-size: 16px; color: var(--ink-muted); }\n  .own-intercom .nav-drawer a:hover { background: var(--surface-1); color: var(--ink); }\n  .own-intercom .nav-drawer .drawer-cta { color: var(--ink); font-weight: 500; }\n  .own-intercom .hero-in { grid-template-columns: 1fr; }\n  .own-intercom .grid3 { grid-template-columns: repeat(2, 1fr); }\n  .own-intercom .mw-grid { grid-template-columns: 1fr 1fr; }\n  .own-intercom .mw-panel:first-child { grid-column: 1 / -1; }\n  .own-intercom .quotes { grid-template-columns: 1fr; }\n  .own-intercom .foot-in { grid-template-columns: 1fr; }\n}\n@container frame (max-width: 760px) {\n  .own-intercom .nav-actions .btn-tertiary { display: none; }\n  .own-intercom .grid3 { grid-template-columns: 1fr; }\n  .own-intercom .mock { grid-template-columns: 1fr; }\n  .own-intercom .mock-side { flex-direction: row; border-right: 0; border-bottom: 1px solid var(--hairline-soft); overflow-x: auto; }\n  .own-intercom .mock-float { left: 12px; }\n  .own-intercom .mw-grid { grid-template-columns: 1fr; }\n  .own-intercom .mw-panel:first-child { grid-column: auto; }\n  .own-intercom .foot-cols { grid-template-columns: repeat(2, 1fr); }\n  .own-intercom .cta { flex-direction: column; align-items: flex-start; }\n}\n@container frame (max-width: 430px) {\n  .own-intercom .hero-cta .btn { width: 100%; }\n  .own-intercom .foot-cols { grid-template-columns: 1fr; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .own-intercom *, .own-intercom *::before, .own-intercom *::after {\n    animation-duration: .001ms !important; animation-iteration-count: 1 !important;\n    transition-duration: .001ms !important;\n  }\n  .own-intercom .reveal { opacity: 1; transform: none; }\n  .own-intercom .faq-a { transition: none; }\n}\n"};
/* ══ INTERCOM — behaviour for the Northwind own layout ═════════════════════
   Renders the inbox list, channels, logo strip and FAQ, wires the billing
   tabs, the accordion, count-up, sticky nav, drawer and reveals. */

(function () {
  window.OWN_LAYOUTS = window.OWN_LAYOUTS || {};

  var INBOX = [
    { who: 'Mira Kessler', msg: 'Shipment 4412 is stuck at customs — can we re-route?', time: '9m', c: '#65b5ff', av: 'MK' },
    { who: 'Daniel Okafor', msg: 'Monthly revenue board looks off in APAC column.', time: '24m', c: '#0bdf50', av: 'DO' },
    { who: 'Lena Sørensen', msg: 'Need the vendor scorecard before the 2pm review.', time: '1h', c: '#ff2067', av: 'LS' },
    { who: 'Amir Haddad', msg: 'Fin answered my question — escalating for the refund.', time: '2h', c: '#b3e01c', av: 'AH' }
  ];
  var CHANNELS = [
    { name: 'Email', w: 74, c: '#65b5ff' },
    { name: 'Live chat', w: 52, c: '#ff5600' },
    { name: 'Phone', w: 30, c: '#03b2cb' },
    { name: 'Fin agent', w: 62, c: '#0bdf50' }
  ];
  var LOGOS = ['Aperture Foods', 'Vector Freight', 'Kestrel Bank', 'Halden Retail', 'Northgate Health', 'Miro Labs'];
  var FAQ = [
    { q: 'Can Northwind replace our current help desk?', a: 'Yes. Import your queues, macros, and tags, then run both side by side for as long as you like before switching over.' },
    { q: 'How does the Fin AI agent decide what to escalate?', a: 'You set the rules and confidence thresholds. Fin resolves the repeat questions and hands the rest to a human with the full conversation attached.' },
    { q: 'Where is our data stored?', a: 'Your choice of region — US, EU, or APAC — with residency guarantees on the Expert plan and an immutable audit log.' },
    { q: 'Is there an API?', a: 'Everything in the UI is available over a REST and webhook API, including tickets, contacts, and reporting events.' }
  ];

  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  window.OWN_LAYOUTS['intercom'] = {
    init: function (root) {
      var reduced = false;
      try { reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { /* ignore */ }

      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      var disposed = false;
      var rafs = [];
      var observers = [];

      function on(el, type, fn, opt) {
        if (!el) return;
        opt = Object.assign({}, opt || {});
        if (signal) opt.signal = signal;
        el.addEventListener(type, fn, opt);
      }
      function raf(fn) { var id = requestAnimationFrame(fn); rafs.push(id); return id; }
      function $(sel) { return root.querySelector(sel); }
      function $$(sel) { return Array.prototype.slice.call(root.querySelectorAll(sel)); }

      /* ── inbox list ────────────────────────────────────────────────── */
      var list = $('#intercomList');
      if (list) {
        list.innerHTML = INBOX.map(function (m) {
          return '<li class="mi">'
            + '<span class="mi-av" style="background:' + m.c + '">' + esc(m.av) + '</span>'
            + '<span class="mi-body"><b>' + esc(m.who) + '</b><span>' + esc(m.msg) + '</span></span>'
            + '<span class="mi-time">' + esc(m.time) + '</span>'
            + '</li>';
        }).join('');
      }

      /* ── channels ──────────────────────────────────────────────────── */
      var ch = $('#intercomChannels');
      if (ch) {
        ch.innerHTML = CHANNELS.map(function (c) {
          return '<li><span class="mr-top"><span>' + esc(c.name) + '</span><b>' + c.w + '%</b></span>'
            + '<span class="mr-bar"><i style="--w:' + c.w + '%;--c:' + c.c + '"></i></span></li>';
        }).join('');
      }

      /* ── logos ─────────────────────────────────────────────────────── */
      var logos = $('#intercomLogos');
      if (logos) {
        logos.innerHTML = '<span class="logos-cap">Trusted by support and operations teams at</span>'
          + LOGOS.map(function (n) { return '<span class="lg">' + esc(n) + '</span>'; }).join('');
      }

      /* ── FAQ accordion ─────────────────────────────────────────────── */
      var faq = $('#intercomFaqList');
      if (faq) {
        faq.innerHTML = FAQ.map(function (f, i) {
          return '<div class="faq-item' + (i === 0 ? ' open' : '') + '">'
            + '<button class="faq-q" type="button" aria-expanded="' + (i === 0) + '">' + esc(f.q)
            + '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 9l6 6 6-6"/></svg></button>'
            + '<div class="faq-a"><div><p>' + esc(f.a) + '</p></div></div>'
            + '</div>';
        }).join('');
      }

      /* ── billing tabs ──────────────────────────────────────────────── */
      var MONTH = { '29': 29, '85': 85, '132': 132 };
      var ANNUAL = { '29': 24, '85': 71, '132': 110 };
      $$('[data-cycle]').forEach(function (tab) {
        on(tab, 'click', function () {
          var cycle = tab.dataset.cycle;
          $$('[data-cycle]').forEach(function (t) {
            var isOn = t === tab;
            t.classList.toggle('on', isOn);
            t.setAttribute('aria-selected', String(isOn));
          });
          $$('[data-price]').forEach(function (el) {
            el.textContent = '$' + (cycle === 'annual' ? ANNUAL : MONTH)[el.dataset.price];
          });
        });
      });

      /* ── count-up ──────────────────────────────────────────────────── */
      function countTo(el, to, ms, suffix) {
        if (reduced) { el.textContent = Math.round(to).toLocaleString('en-US') + suffix; return; }
        var from = 0, t0 = null;
        function step(t) {
          if (disposed) return;
          if (t0 === null) t0 = t;
          var k = Math.min(1, (t - t0) / ms), e = 1 - Math.pow(1 - k, 4);
          el.textContent = Math.round(from + (to - from) * e).toLocaleString('en-US') + suffix;
          if (k < 1) raf(step);
        }
        raf(step);
      }

      /* ── reveals ───────────────────────────────────────────────────── */
      var io = null;
      if (!reduced && typeof IntersectionObserver !== 'undefined') {
        io = new IntersectionObserver(function (ents) {
          ents.forEach(function (en) {
            if (en.isIntersecting) {
              en.target.classList.add('in');
              if (en.target.dataset.count) countTo(en.target, Number(en.target.dataset.count), 1100, en.target.dataset.suffix || '');
              io.unobserve(en.target);
            }
          });
        }, { rootMargin: '0px 0px -8% 0px', threshold: 0.12 });
        observers.push(io);
      }
      $$('[data-reveal]').forEach(function (el) { if (io) io.observe(el); else el.classList.add('in'); });
      $$('[data-count]').forEach(function (el) {
        if (io) io.observe(el);
        else el.textContent = Number(el.dataset.count).toLocaleString('en-US') + (el.dataset.suffix || '');
      });

      /* ── sticky nav + drawer ───────────────────────────────────────── */
      var nav = $('#intercomNav');
      function onScroll() {
        if (disposed || !nav) return;
        nav.classList.toggle('is-stuck', root.getBoundingClientRect().top < -8);
      }
      on(window, 'scroll', onScroll, { passive: true });
      onScroll();

      var toggle = $('[data-nav-toggle]');
      var drawer = $('[data-nav-drawer]');
      on(toggle, 'click', function () {
        if (!drawer) return;
        var next = drawer.hidden;
        drawer.hidden = !next;
        toggle.setAttribute('aria-expanded', String(next));
      });

      /* ── faq clicks ────────────────────────────────────────────────── */
      on(faq, 'click', function (e) {
        var btn = e.target.closest('.faq-q');
        if (!btn) return;
        var item = btn.closest('.faq-item');
        var isOpen = item.classList.toggle('open');
        btn.setAttribute('aria-expanded', String(isOpen));
      });

      /* ── smooth scroll ─────────────────────────────────────────────── */
      $$('a[href^="#"]').forEach(function (a) {
        on(a, 'click', function (e) {
          var href = a.getAttribute('href');
          if (!href || href.length < 2) return;
          var target = root.querySelector(href);
          if (!target) return;
          e.preventDefault();
          target.scrollIntoView({ behavior: reduced ? 'auto' : 'smooth', block: 'start' });
          if (drawer && !drawer.hidden) { drawer.hidden = true; toggle.setAttribute('aria-expanded', 'false'); }
        });
      });

      return function cleanup() {
        disposed = true;
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
        rafs.forEach(function (id) { cancelAnimationFrame(id); });
        observers.forEach(function (o) { try { o.disconnect(); } catch (e) { /* ignore */ } });
      };
    }
  };
})();
